
INSERT INTO service_translations (service_id, language_id, title, short_description, long_description, seo_title, meta_description) VALUES
('3f3337e7-3b57-4cbe-b6e4-c304273f02e4', 1, 'Google Ads Agency', 'Certified Google Ads agency managing Search, Display, Shopping, and YouTube campaigns for maximum ROI.', '<h2>Why Choose Advisable as Your Google Ads Agency</h2><p>As a <strong>Google Premier Partner</strong>, we deliver high-performance campaigns across Search, Display, Shopping, and YouTube with data-driven optimization.</p><h3>Our Google Ads Services</h3><ul><li><strong>Search Campaigns</strong> — Intent-based targeting for bottom-funnel conversions.</li><li><strong>Display & Video</strong> — Awareness and remarketing campaigns.</li><li><strong>Shopping Campaigns</strong> — Product feed optimization and PMAX.</li><li><strong>Analytics & Reporting</strong> — Conversion tracking and attribution.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/google-ads-campaigns">Google Ads Campaigns →</a></li><li><a href="/digital-agency/paid-growth-systems">Paid Growth Systems →</a></li><li><a href="/contact">Get a free PPC audit →</a></li></ul>', 'Google Ads Agency | Advisable', 'Certified Google Ads agency. Search, Display, Shopping & YouTube campaigns optimized for maximum ROI. Free PPC audit available.'),

('1e0892a8-c5a7-435c-835d-af063cc845d0', 1, 'Link Building Agency', 'White-hat link building agency securing high-authority backlinks through digital PR and content-driven outreach.', '<h2>Why Choose Advisable as Your Link Building Agency</h2><p>We build <strong>high-quality backlink profiles</strong> through ethical, content-driven strategies that boost domain authority and organic rankings.</p><h3>Our Link Building Services</h3><ul><li><strong>Digital PR</strong> — Media placements and press coverage.</li><li><strong>Guest Posting</strong> — Content on relevant, high-authority sites.</li><li><strong>Broken Link Building</strong> — Recovering lost link equity.</li><li><strong>Link Audit & Disavow</strong> — Cleaning toxic backlink profiles.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/seo-ai-visibility">SEO & AI Visibility →</a></li><li><a href="/digital-agency/content-creation">Content Creation →</a></li><li><a href="/contact">Build your authority →</a></li></ul>', 'Link Building Agency | Advisable', 'White-hat link building agency. High-authority backlinks through digital PR & content outreach that boost your domain authority and rankings.'),

('a4b129d8-cdad-4d94-907a-8ec31b7f484f', 1, 'Technical SEO Agency', 'Specialized technical SEO agency optimizing site speed, crawlability, structured data, and Core Web Vitals.', '<h2>Why Choose Advisable as Your Technical SEO Agency</h2><p>We fix the <strong>technical foundations</strong> that prevent your site from ranking — speed, crawlability, indexation, and structured data.</p><h3>Our Technical SEO Services</h3><ul><li><strong>Site Speed Optimization</strong> — Core Web Vitals and performance tuning.</li><li><strong>Crawl & Indexation</strong> — Fixing crawl errors and XML sitemaps.</li><li><strong>Structured Data</strong> — Schema markup for rich results.</li><li><strong>Site Architecture</strong> — URL structure, internal linking, and canonicalization.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/seo-audit">SEO Audit →</a></li><li><a href="/digital-agency/seo-ai-visibility">SEO & AI Visibility →</a></li><li><a href="/contact">Fix your technical SEO →</a></li></ul>', 'Technical SEO Agency | Advisable', 'Technical SEO agency optimizing site speed, crawlability & Core Web Vitals. Fix technical issues holding back your search rankings.'),

('3e5f3558-9143-428a-8eca-81ccad35603e', 1, 'eCommerce SEO Agency', 'Dedicated eCommerce SEO agency optimizing product pages and category structures to drive organic revenue.', '<h2>Why Choose Advisable as Your eCommerce SEO Agency</h2><p>We specialize in <strong>eCommerce SEO</strong> — optimizing product pages, category structures, and technical SEO to drive organic revenue for online stores.</p><h3>Our eCommerce SEO Services</h3><ul><li><strong>Product Page Optimization</strong> — Titles, descriptions, and schema markup.</li><li><strong>Category SEO</strong> — Taxonomy, filters, and faceted navigation.</li><li><strong>Technical eCommerce SEO</strong> — Site speed, crawl budget, and duplicate content.</li><li><strong>Content Strategy</strong> — Buying guides, comparisons, and blog content.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/seo-ai-visibility">SEO & AI Visibility →</a></li><li><a href="/digital-agency/e-commerce-solutions">E-commerce Solutions →</a></li><li><a href="/contact">Get a free eCommerce SEO audit →</a></li></ul>', 'eCommerce SEO Agency | Advisable', 'eCommerce SEO agency driving organic revenue. Product page optimization, category SEO & technical fixes for online stores. Free audit.'),

('e99f9e30-47ea-43ef-ac06-17e9990fef2d', 1, 'B2C Marketing Agency', 'Dynamic B2C marketing agency creating engaging consumer campaigns that drive brand awareness and sales.', '<h2>Why Choose Advisable as Your B2C Marketing Agency</h2><p>We create <strong>consumer-first campaigns</strong> that build emotional connections, drive engagement, and convert across social, paid, and email channels.</p><h3>Our B2C Marketing Services</h3><ul><li><strong>Social Media Campaigns</strong> — Platform-native content that resonates.</li><li><strong>Paid Media</strong> — Multi-channel advertising strategies.</li><li><strong>Email & SMS Marketing</strong> — Lifecycle campaigns that convert.</li><li><strong>Brand Experiences</strong> — Memorable moments that build loyalty.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/marketing-growth">Marketing & Growth →</a></li><li><a href="/digital-agency/social-media-management">Social Media Management →</a></li><li><a href="/contact">Launch your campaign →</a></li></ul>', 'B2C Marketing Agency | Advisable', 'B2C marketing agency driving consumer engagement. Social media, paid ads & email campaigns that build brand love and drive sales.'),

('8f9868c8-bc5e-4ab0-9542-50e1ac26b351', 1, 'Fintech Marketing Agency', 'Specialized fintech marketing agency building trust-driven campaigns for financial technology products.', '<h2>Why Choose Advisable as Your Fintech Marketing Agency</h2><p>We understand the <strong>unique challenges of fintech</strong> — regulatory compliance, trust-building, and complex user journeys. Our strategies are designed for the financial technology sector.</p><h3>Our Fintech Marketing Services</h3><ul><li><strong>Compliance-First Campaigns</strong> — Advertising that meets regulatory standards.</li><li><strong>Trust & Authority Building</strong> — Content and PR strategies.</li><li><strong>User Acquisition</strong> — Performance campaigns optimized for CAC.</li><li><strong>Product Marketing</strong> — Positioning and messaging for financial products.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/marketing-growth">Marketing & Growth →</a></li><li><a href="/digital-agency/performance-marketing">Performance Marketing →</a></li><li><a href="/contact">Talk to our fintech experts →</a></li></ul>', 'Fintech Marketing Agency | Advisable', 'Fintech marketing agency experts. Compliant, trust-driven campaigns that acquire users for banking, payments & financial technology products.'),

('5744f3a7-c8e1-4515-b239-c7d1b520a9b6', 1, 'Healthcare Marketing Agency', 'Healthcare marketing agency helping clinics, medtech, and pharma companies reach patients through compliant digital strategies.', '<h2>Why Choose Advisable as Your Healthcare Marketing Agency</h2><p>We deliver <strong>compliant healthcare marketing</strong> that reaches patients and providers while respecting regulatory requirements.</p><h3>Our Healthcare Marketing Services</h3><ul><li><strong>Patient Acquisition</strong> — Local SEO, PPC, and content strategies for clinics.</li><li><strong>Medtech & Pharma Marketing</strong> — B2B campaigns for medical technology.</li><li><strong>Compliant Content</strong> — Medical content reviewed for accuracy.</li><li><strong>Reputation Management</strong> — Patient reviews and online presence.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/marketing-growth">Marketing & Growth →</a></li><li><a href="/digital-agency/content-creation">Content Creation →</a></li><li><a href="/contact">Discuss healthcare marketing →</a></li></ul>', 'Healthcare Marketing Agency | Advisable', 'Healthcare marketing agency with compliance expertise. Digital strategies for clinics, medtech & pharma that reach patients and providers.'),

('395b9305-656d-4925-b0ae-0c651fa3a867', 1, 'Real Estate Marketing Agency', 'Results-driven real estate marketing agency generating qualified buyer and seller leads through targeted digital strategies.', '<h2>Why Choose Advisable as Your Real Estate Marketing Agency</h2><p>We help <strong>real estate professionals</strong> generate qualified leads through targeted advertising, local SEO, and property marketing strategies.</p><h3>Our Real Estate Marketing Services</h3><ul><li><strong>Lead Generation</strong> — Targeted ads for buyers and sellers.</li><li><strong>Local SEO</strong> — Dominating neighborhood searches.</li><li><strong>Property Marketing</strong> — Listings, virtual tours, and video content.</li><li><strong>Social Media</strong> — Building agent brand presence.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/google-ads-campaigns">Google Ads Campaigns →</a></li><li><a href="/digital-agency/seo-ai-visibility">SEO & AI Visibility →</a></li><li><a href="/contact">Get more property leads →</a></li></ul>', 'Real Estate Marketing Agency | Advisable', 'Real estate marketing agency generating qualified leads. Targeted ads, local SEO & property marketing that drives buyer and seller inquiries.'),

('7473ead8-c5b9-44e9-b4c1-2d96b833048d', 1, 'Startup Marketing Agency', 'Agile startup marketing agency helping early-stage and growth-stage startups validate messaging and scale efficiently.', '<h2>Why Choose Advisable as Your Startup Marketing Agency</h2><p>We help startups <strong>go from zero to traction</strong> with lean, data-driven marketing strategies that validate positioning and drive user acquisition.</p><h3>Our Startup Marketing Services</h3><ul><li><strong>Go-to-Market Strategy</strong> — Positioning, messaging, and launch planning.</li><li><strong>Growth Hacking</strong> — Rapid experimentation for early traction.</li><li><strong>User Acquisition</strong> — Paid and organic channels optimized for CAC.</li><li><strong>Investor Marketing</strong> — Pitch support and brand building.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/marketing-growth">Marketing & Growth →</a></li><li><a href="/digital-agency/paid-growth-systems">Paid Growth Systems →</a></li><li><a href="/contact">Launch smarter →</a></li></ul>', 'Startup Marketing Agency | Advisable', 'Startup marketing agency for early & growth-stage companies. Go-to-market strategy, user acquisition & growth hacking. Launch smarter.'),

('a8460e3b-0a41-4bad-afc8-3b7958610092', 1, 'Full Service Agency', 'Full-service digital agency offering end-to-end marketing, design, and development solutions under one roof.', '<h2>Why Choose Advisable as Your Full Service Agency</h2><p>We offer <strong>end-to-end digital solutions</strong> — from strategy and design to development and marketing — all under one roof for seamless execution.</p><h3>Our Full Service Capabilities</h3><ul><li><strong>Digital Strategy</strong> — Comprehensive roadmaps aligned to business goals.</li><li><strong>Design & Branding</strong> — Visual identity, UX/UI, and creative production.</li><li><strong>Development</strong> — Web, mobile, and application development.</li><li><strong>Marketing & Growth</strong> — SEO, paid media, social, and content.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/marketing-growth">Marketing & Growth →</a></li><li><a href="/digital-agency/web-development">Web Development →</a></li><li><a href="/contact">Start your project →</a></li></ul>', 'Full Service Digital Agency | Advisable', 'Full-service digital agency. Strategy, design, development & marketing under one roof. End-to-end solutions that drive business growth.'),

('bdc986bd-8474-4b68-a841-5dc88deef410', 1, 'Creative Agency', 'Bold creative agency producing breakthrough campaigns, visual identities, and digital experiences.', '<h2>Why Choose Advisable as Your Creative Agency</h2><p>We create <strong>bold, unforgettable creative</strong> that makes brands impossible to ignore — from visual identities to digital campaigns.</p><h3>Our Creative Services</h3><ul><li><strong>Campaign Concepting</strong> — Big ideas that cut through the noise.</li><li><strong>Visual Identity</strong> — Brand design systems that scale.</li><li><strong>Digital Experiences</strong> — Interactive and immersive web experiences.</li><li><strong>Content Production</strong> — Photo, video, and motion graphics.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/ai-creative-studio">AI Creative Studio →</a></li><li><a href="/digital-agency/brand-strategy">Brand Strategy →</a></li><li><a href="/contact">Create something bold →</a></li></ul>', 'Creative Agency | Advisable', 'Creative agency crafting bold campaigns & brand experiences. From visual identity to digital campaigns that make your brand unforgettable.');
